window.ENEM_RESOLUTIONS=[{"id":"M549","title":"Ler dois gráficos sem misturar suas bases","steps":["No gráfico de 2024, some as matrículas: 280 + 80 + 20 + 20 = 400. Esse é o total previsto para 2025.","No gráfico de 2023, o setor verde do francês corresponde a 10%. A pergunta combina o total de um ano com a proporção do outro.","Calcule 10% de 400: 0,10 × 400 = 40 matrículas. Não se pede o número de franceses em 2024."],"alternatives":{"A":"2 seria 10% de 20, usando indevidamente como base apenas o francês de 2024.","B":"12 não corresponde a 10% do total previsto de 400; a base deve reunir todos os idiomas.","C":"20 repete a quantidade de francês em 2024, em vez de aplicar a distribuição de 2023.","D":"22 seria aumentar 20 em 10%; o comando não pede crescimento do curso em relação a 2024.","E":"40 combina corretamente o total 400 com a participação de 10% do francês."},"takeaway":"Antes de multiplicar uma porcentagem, escreva: porcentagem de quê? Neste item, cada gráfico fornece uma informação diferente.","authored":true,"key":"matematica:M549","answer":"E","year":2025,"number":147,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"M003","title":"Produção por funcionário-hora","steps":["As condições iniciais representam 3 × 6 = 18 funcionário-horas por dia. A produtividade é 720 ÷ 18 = 40 tijolos por funcionário-hora.","Depois da mudança, a fábrica dispõe de 5 × 9 = 45 funcionário-horas por dia. O texto garante a mesma produtividade em qualquer jornada.","Portanto, a nova produção é 45 × 40 = 1 800 tijolos. Equivalentemente: 720 × (5/3) × (9/6)."],"alternatives":{"A":"800 não mantém a taxa de 40 tijolos por funcionário-hora: 800/45 é menor que essa produtividade.","B":"1 080 considera apenas a ampliação das horas: 720 × 9/6. Deixa de considerar os dois funcionários adicionais.","C":"1 200 considera apenas o aumento de funcionários: 720 × 5/3. Mantém indevidamente a jornada antiga.","D":"1 800 considera os dois aumentos proporcionais, sem mudar a produtividade individual.","E":"2 520 corresponde a um fator 3,5 sobre 720; o fator conjunto correto é (5/3)(9/6) = 2,5."},"takeaway":"Em proporção composta, compare cada grandeza mantendo as demais fixas; não some os fatores de crescimento.","authored":true,"key":"matematica:M003","answer":"D","year":2025,"number":150,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"M119","title":"A escala linear precisa ser elevada ao quadrado","steps":["A escala 1:200 divide comprimentos por 200. Como área depende de duas dimensões, divide-se a área real por 200² = 40 000.","A área da maquete é 1 672/40 000 = 0,0418 m². Agora converta: 1 m² = 10 000 cm².","Assim, 0,0418 × 10 000 = 418 cm². A conversão pode ser feita antes ou depois, desde que também seja quadrática."],"alternatives":{"A":"4,18 cm² é cem vezes menor que 418 cm²; não resulta da escala de área e da conversão pedidas.","B":"8,36 é o quociente 1 672/200: aplica à área uma escala apenas linear e ainda não fornece o resultado em cm².","C":"41,80 cm² é dez vezes menor que o resultado; reveja o fator 10 000 entre m² e cm².","D":"83,60 cm² não satisfaz A_maquete = A_real/200² após converter as unidades.","E":"418,00 cm² usa corretamente tanto o quadrado da escala quanto o quadrado da conversão de comprimento."},"takeaway":"Comprimento usa k; área usa k²; volume usa k³. Anote a unidade ao lado de cada etapa.","authored":true,"key":"matematica:M119","answer":"E","year":2024,"number":151,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true}},{"id":"M702","title":"Uma desigualdade de probabilidade, não só uma proporção","steps":["Na urna B, quatro pretas correspondem a 25%: o total inicial é 4/0,25 = 16, com 12 brancas. Se x brancas forem adicionadas, P(preta em B) = 4/(16+x).","As retiradas de urnas diferentes são independentes. A chance de voucher é 0,20 × 4/(16+x), e deve ser no máximo 0,01.","Resolva: 0,8/(16+x) ≤ 0,01. Como o denominador é positivo, 16+x ≥ 80, logo x ≥ 64. Pede-se o mínimo, portanto 64."],"alternatives":{"A":"Com 20 adicionais, a chance é 0,8/36 ≈ 2,22%, ainda maior que 1%.","B":"Com 60 adicionais, a chance é 0,8/76 ≈ 1,05%, ligeiramente acima do limite.","C":"Com 64 adicionais, a chance é 0,8/80 = 1%; é o primeiro inteiro que atende à condição.","D":"68 também reduz a chance para menos de 1%, mas não é a quantidade mínima solicitada.","E":"80 também atende ao limite, porém adiciona mais bolinhas que o necessário; não é o total final que se pede."},"takeaway":"Diferencie quantidade adicionada, quantidade de brancas e total da urna. Verifique o sentido de “menor ou igual” e de “mínimo”.","authored":true,"key":"matematica:M702","answer":"C","year":2023,"number":138,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true}},{"id":"M640","title":"Reconstruir a soma a partir de duas médias","steps":["Se S é a soma das quatro notas, a média correta é S/4. O cálculo equivocado foi S/5.","O resultado errado ficou uma unidade abaixo do correto: S/4 − S/5 = 1. Assim, S/20 = 1 e S = 20.","A pergunta pede a média correta, não a soma: 20/4 = 5. A média errada seria 4, confirmando a diferença de uma unidade."],"alternatives":{"A":"4 é a média calculada com o divisor errado, 20/5.","B":"5 é a média correta; produz a diferença 5−4 = 1 exigida pelo texto.","C":"Se a média correta fosse 6, a errada seria 4,8, dando diferença de 1,2, não 1.","D":"Se a média fosse 19, a diferença entre a correta e a errada seria 19/5 = 3,8.","E":"Se a média fosse 21, a diferença seria 21/5 = 4,2; não atende à condição."},"takeaway":"Uma média com divisor 5, quando deveria ser 4, vale 4/5 da correta. Recoloque o resultado na situação para conferir.","authored":true,"key":"matematica:M640","answer":"B","year":2024,"number":137,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true}},{"id":"M445","title":"Conservação do volume na reciclagem","steps":["O cilindro tem volume V = πr²h = π × 4² × 50 = 800π cm³. Não há perda de metal.","Cada esfera tem DIÂMETRO de 1 cm, então o raio é 0,5 cm. Seu volume é (4/3)π(0,5)³ = π/6 cm³.","Divida o volume disponível pelo de uma esfera: 800π ÷ (π/6) = 4 800. O π cancela; o número de peças é inteiro."],"alternatives":{"A":"800 é o coeficiente do volume do cilindro, não a quantidade obtida ao dividir pelos volumes das esferas.","B":"1 200 não resulta da razão 800π/(π/6); é necessário usar o raio da esfera elevado ao cubo.","C":"2 400 corresponde à metade da quantidade calculada; não conserva todo o volume na razão correta.","D":"4 800 resulta da conservação do volume e do uso de raio 0,5 cm para cada esfera.","E":"6 400 exigiria mais metal que os 800π cm³ disponíveis, mantendo as dimensões dadas."},"takeaway":"Escreva primeiro as fórmulas com unidades. Trocar diâmetro por raio altera o volume de uma esfera por fator oito.","authored":true,"key":"matematica:M445","answer":"D","year":2022,"number":174,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true}},{"id":"M075","title":"Porcentagem como número decimal","steps":["O símbolo % significa “por cem”. A taxa 135,25% equivale a 135,25/100.","Dividindo por cem, a vírgula avança duas casas para a esquerda: 1,3525.","Trata-se da taxa de crescimento, não do fator que transforma população inicial em final. Esse fator seria 1 + 1,3525 = 2,3525, que não foi perguntado."],"alternatives":{"A":"13 525,0 multiplica a taxa por cem, em vez de dividi-la.","B":"135,25 apenas retira o símbolo %, sem realizar a conversão.","C":"13,525 divide apenas por dez; ainda é dez vezes maior que a taxa decimal.","D":"1,3525 é exatamente 135,25 dividido por cem.","E":"0,13525 divide por mil; corresponderia a 13,525%, não a 135,25%."},"takeaway":"Uma taxa maior que 100% pode ser um decimal maior que 1. Não force o resultado para o intervalo entre zero e um.","authored":true,"key":"matematica:M075","answer":"D","year":2024,"number":153,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true}},{"id":"M224","title":"O que permanece constante na mistura?","steps":["A fração de S₂ inicialmente é 0,05% = 0,0005. Seu volume é 10 × 0,0005 = 0,005 L e não será retirado.","No final, S₁ será 99,90%, portanto S₂ deverá ser 0,10% = 0,001 do novo total V. Assim, 0,001V = 0,005 e V = 5 L.","O recipiente começou com 10 L e ficará com 5 L: retiram-se 5 L, exclusivamente de S₁. Restam 4,995 L de S₁ em 5 L, ou 99,90%."],"alternatives":{"A":"0,0050 L é o volume de S₂ que permanece; não é o volume de S₁ a retirar.","B":"0,0100 L não reduz o volume total a 5 L, condição necessária para dobrar a participação de S₂.","C":"0,5000 L deixaria 9,5 L no recipiente; 0,005/9,5 não é 0,10%.","D":"4,9775 L deixaria 5,0225 L; o denominador necessário é exatamente 5 L.","E":"5,0000 L mantém 0,005 L de S₂ e deixa o total em 5 L, atendendo às duas concentrações."},"takeaway":"Quando um componente fica constante e sua porcentagem dobra, o volume total cai à metade neste modelo de mistura.","authored":true,"key":"matematica:M224","answer":"E","year":2025,"number":140,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"M226","title":"Traduzir uma meta de custo em inequação","steps":["Reciclar uma tonelada custa 500 reais, que são 5% do custo virgem. Logo, o custo virgem é 500/0,05 = 10 000 reais por tonelada.","A produção atual é 190 t e custa 110×10 000 + 80×500 = 1 140 000 reais. A meta permite no máximo a metade: 570 000 reais.","Se x toneladas forem recicladas, 190−x serão virgens. Impomos 500x + 10 000(190−x) ≤ 570 000, obtendo x ≥ 140. Com 140 t recicladas e 50 t virgens, o custo é exatamente 570 000."],"alternatives":{"A":"135 t dariam custo de 617 500 reais, acima do limite.","B":"140 t atingem a redução de 50% e são a quantidade mínima que satisfaz a inequação.","C":"155 t dão custo de 427 500 reais: atendem à meta, mas não são o mínimo.","D":"160 t dão custo de 380 000 reais: é uma solução possível, porém maior que o mínimo pedido.","E":"175 t dão custo de 237 500 reais: economizam mais, mas excedem a reciclagem mínima necessária."},"takeaway":"Percentual de redução incide sobre o custo antigo. Mantenha fixa a massa total e teste a alternativa-limite.","authored":true,"key":"matematica:M226","answer":"B","year":2025,"number":162,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"M168","title":"Perda fixa não é perda percentual","steps":["No primeiro envio, saíram 10 200 L e chegaram 9 900 L. Portanto, o descarte fixo é 300 L por transporte.","O novo pedido é o dobro do volume ENCOMENDADO antes: 2 × 10 000 = 20 000 L entregues. Não é o dobro do volume enviado nem do recebido.","Para compensar a mesma perda de 300 L, devem sair 20 000 + 300 = 20 300 L. Esse volume cabe no caminhão de 30 000 L."],"alternatives":{"A":"20 100 L enviados entregariam 19 800 L, abaixo do pedido.","B":"20 200 L entregariam 19 900 L, ainda insuficientes.","C":"20 300 L menos a perda fixa de 300 L entregam exatamente os 20 000 L pedidos.","D":"20 400 L garantem a entrega, mas não são o volume mínimo: sobram 100 L.","E":"20 600 L dobram também a perda de 300 L, contrariando a informação de descarte fixo por viagem."},"takeaway":"Sublinhe a base do dobro e a palavra “independe”. Uma perda constante é modelada por soma/subtração, não por porcentagem.","authored":true,"key":"matematica:M168","answer":"C","year":2025,"number":141,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"L488","title":"Filosofia como enfrentamento de problemas sociais","steps":["Leia o comando: procura-se o OBJETIVO da autora, não a tradução de uma palavra isolada.","Davis condiciona o valor da filosofia à relevância para problemas humanos e à redução da miséria. No final, explicita pobreza, necessidade econômica e opressão mental.","A referência a Sócrates reforça essa defesa: ensinar a viver adequadamente é reinterpretado como libertar-se de problemas urgentes. A finalidade é aproximar reflexão e vida social."],"alternatives":{"A":"Não se critica uma suposta restrição de temas; exige-se relevância para problemas concretos.","B":"O texto não restringe a filosofia à universidade: aproxima-a das necessidades humanas.","C":"Sócrates é mobilizado como apoio, não como posição a ser abandonada.","D":"Problemas sociais são explicitados e apresentados como critério de relevância da filosofia.","E":"A filosofia é convocada a combater a pobreza; não é acusada de causá-la."},"takeaway":"Expressões como “if … then” organizam a condição central do argumento. Traduza a relação entre ideias, não só palavras próximas das alternativas.","authored":true,"key":"linguagens:L488","answer":"D","year":2025,"number":2,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"L489","title":"A integração entre pessoa e natureza no poema","steps":["Observe a repetição de “Remember”: ela conduz o leitor a recordar vínculos, não somente a enumerar astros.","O percurso vai do céu à origem corporal, à terra e aos outros seres vivos. A formulação “we are earth” aproxima a identidade humana do ambiente.","O fechamento relaciona pessoa, coletividade e universo. A leitura que reúne esse percurso é a relação entre seres humanos e natureza, e não um elemento isolado da enumeração."],"alternatives":{"A":"Os astros aparecem, mas sua potência não sintetiza a ligação também com terra, plantas, animais e pessoas.","B":"Não se explica a origem biológica de plantas e animais; esses seres participam de uma rede de pertencimento.","C":"A terra não está reduzida ao local de nascimento: a identificação é com a natureza e o universo.","D":"Reúne as imagens de corpo, terra, vida não humana e universo que estruturam o poema.","E":"O texto não estabelece oposição entre tempo real e imaginário; esse contraste foi acrescentado pela alternativa."},"takeaway":"Em poemas, procure a imagem que conecta as partes. Uma opção que apenas repete um substantivo do início pode ser estreita demais.","authored":true,"key":"linguagens:L489","answer":"D","year":2025,"number":3,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"L722","title":"Transformação tecnológica sem desaparecimento do rádio","steps":["O texto acompanha o rádio ao longo do tempo e menciona expectativas de sua substituição pela televisão.","Em seguida, mostra que ele permaneceu e foi incorporado à internet e a dispositivos móveis, chegando à web rádio e ao podcast.","A conclusão apresenta o podcast como continuidade/evolução. Portanto, a reflexão combina permanência do meio e transformação digital, sem afirmar vitória absoluta de um formato."],"alternatives":{"A":"O foco histórico é o rádio, não o desenvolvimento da televisão a partir do digital.","B":"Não há demonstração de predomínio do podcast sobre o rádio; enfatiza-se continuidade e reinvenção.","C":"Expressa os dois movimentos do texto: permanência do rádio e evolução tecnológica.","D":"A TV aparece como substituta esperada que não eliminou o rádio, não como causa da transformação do radiojornalismo.","E":"Interações humanas são um tema mais amplo; não sintetizam a trajetória específica explicada."},"takeaway":"Evite alternativas que inventam substituição total quando o texto fala em coexistência, adaptação ou continuidade.","authored":true,"key":"linguagens:L722","answer":"C","year":2025,"number":39,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"L087","title":"Exemplos iniciais e argumento de generalização","steps":["O comando delimita a estratégia usada PARA INTRODUZIR a fiscalização que afeta todas as mulheres. Volte às primeiras frases.","A autora enumera críticas a Margot Robbie e Paolla Oliveira, mulheres socialmente associadas a padrões de beleza.","Se até elas são julgadas como inadequadas, a vigilância não poupa ninguém. O comentário sobre si e a citação de Naomi Wolf ampliam a discussão depois, mas não são a enumeração inicial pedida."],"alternatives":{"A":"O comentário sobre a própria imagem aparece, porém vem depois dos exemplos que introduzem o raciocínio.","B":"Os parênteses marcam avaliações, mas não constituem a estratégia inicial destacada.","C":"A expressão reality show funciona como comparação da vigilância; não é a enumeração que abre o texto.","D":"A citação de autoridade participa da argumentação posteriormente; não introduz o tema nas frases iniciais.","E":"A sequência de críticas às duas mulheres consideradas padrões de beleza fornece os exemplos de abertura."},"takeaway":"Uma alternativa pode descrever algo verdadeiro do texto e ainda errar o recorte “introduzir”, “concluir” ou “exemplificar”.","authored":true,"key":"linguagens:L087","answer":"E","year":2025,"number":35,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"L088","title":"A função argumentativa de um dado numérico","steps":["Identifique a afirmação a sustentar: influenciadores negros relatam menor alcance que brancos, mesmo em situações semelhantes.","O experimento narrado troca a representação nas fotografias e apresenta aumento de 6 000% no alcance. O número é usado como evidência impactante da desigualdade descrita.","No raciocínio do TEXTO, essa estatística reforça a associação entre circulação digital e viés racial. A questão avalia a função argumentativa, não autoriza generalizar um único relato como prova causal universal de todo algoritmo."],"alternatives":{"A":"A repercussão do projeto não é o ponto central da comparação racial apresentada.","B":"O dado mede variação de alcance, não quantidade de postagens da população negra.","C":"O texto não usa a estatística para promover o site; usa-a para sustentar a denúncia.","D":"Não se avalia a qualidade artística ou técnica das publicações.","E":"Corresponde à intenção de sustentar, com o dado final, a relação entre alcance digital e viés racial."},"takeaway":"Pergunte que tese o número procura apoiar. Não confunda o indicador medido (alcance) com número de posts ou qualidade de conteúdo.","authored":true,"key":"linguagens:L088","answer":"E","year":2024,"number":17,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true}},{"id":"L363","title":"Medos individuais atravessados pela condição social","steps":["Liste os núcleos de angústia: entrada na faculdade, emprego, valor do diploma, ação policial e acesso a direitos.","A repetição articula diferentes esferas da vida. A escola é apenas uma delas; mesmo com diploma o narrador teme desemprego e tratamento hostil.","A alternativa que abarca essas dimensões é a incerteza centrada em sua condição social. Não se trata apenas de indecisão sobre carreira nem de preocupação com a família."],"alternatives":{"A":"A mãe é interlocutora, mas os receios não se concentram no futuro familiar.","B":"O narrador menciona dificuldades escolares, mas antecipa riscos que permanecem mesmo com um diploma.","C":"Integra educação, trabalho, segurança e direitos, dimensões sociais dos medos reiterados.","D":"A formação profissional é parte do problema, não sua abrangência principal.","E":"A referência ao governo não reduz o conjunto de angústias a políticas assistenciais."},"takeaway":"Na interpretação literária, escolha a síntese que explica a recorrência das imagens, sem reduzir o conflito ao primeiro exemplo.","authored":true,"key":"linguagens:L363","answer":"C","year":2025,"number":21,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"L004","title":"Um poema pode incorporar carta e receita","steps":["Reconheça a mistura: há interlocutora nomeada e despedida, como em carta; ingredientes e procedimentos, como em receita.","O comando pergunta o que define o texto COMO POEMA apesar dessas marcas. Observe a construção expressiva, o ritmo, os versos e a atribuição de estados humanos ao feijão e ao preparo.","Assim, não basta tratar de culinária. A organização estética e expressiva da linguagem transforma os materiais de outros gêneros em composição poética."],"alternatives":{"A":"Nomear Helena aproxima o texto de uma carta, mas não distingue a poesia.","B":"Intimidade pode estar em cartas e conversas; não é o traço definidor solicitado.","C":"Descrever procedimentos é marca da receita incorporada, não o elemento que a torna poema.","D":"A exploração expressiva da linguagem explica o trabalho poético sobre carta e receita.","E":"Ingredientes pertencem ao conteúdo culinário e também apareceriam numa receita não literária."},"takeaway":"Gêneros podem dialogar. Diferencie as marcas emprestadas de outro gênero do funcionamento dominante que o comando pede.","authored":true,"key":"linguagens:L004","answer":"D","year":2024,"number":42,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true}},{"id":"L047","title":"Função social de uma reportagem e protagonismo feminino","steps":["O texto traz vários dados factuais, mas abre com uma ruptura: a sucessão masculina é quebrada pela liderança de uma mulher.","A narrativa acompanha sua atuação e volta à sucessão, agora com duas filhas escolhidas para continuar a missão.","Essa moldura dá centralidade à agência feminina. Quantidade de famílias, reconhecimento oficial e luta por terra compõem o contexto, sem substituir o eixo destacado pelo conjunto."],"alternatives":{"A":"O número de famílias é informação contextual, não a função social central da abordagem.","B":"A narrativa ressalta justamente uma mudança numa tradição masculina, não apenas a força de conservar costumes.","C":"A demarcação está nas lutas mencionadas, mas não resume a construção narrativa sobre liderança e sucessão.","D":"Identifica o protagonismo da cacique e das filhas na linha sucessória, eixo reiterado do relato.","E":"O reconhecimento governamental é uma conquista narrada, porém não sintetiza a ênfase na liderança das mulheres."},"takeaway":"Veja o que reaparece na abertura e no fechamento. Função social não é sinônimo de qualquer dado verdadeiro da reportagem.","authored":true,"key":"linguagens:L047","answer":"D","year":2025,"number":43,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"L220","title":"Linguagem ligada à ocupação profissional","steps":["Observe a situação: mesmo quando recebe perguntas pessoais, o entrevistado responde de modo técnico e professoral.","Termos e comentários sobre filologia, lexicologia e empréstimos linguísticos remetem a sua área de trabalho.","Essa recorrência caracteriza uma variedade ocupacional. Idade e origem regional são dados biográficos, mas não explicam as marcas linguísticas efetivamente selecionadas pelo texto."],"alternatives":{"A":"O próprio relato mostra que o tom técnico persiste em perguntas pessoais; não decorre apenas de exigência situacional de formalidade.","B":"Não são destacadas marcas do falar pernambucano, e sim termos da profissão.","C":"A formação pode influenciar o repertório, mas o ponto preciso é o vocabulário especializado, não a obrigação de linguagem rebuscada.","D":"A idade de 95 anos não demonstra que os termos sejam exclusivos de sua geração.","E":"Relaciona os usos linguísticos específicos à atuação como filólogo e gramático."},"takeaway":"Classifique pelas marcas observadas, não por informações biográficas isoladas. Variação ocupacional não significa falar “melhor”.","authored":true,"key":"linguagens:L220","answer":"E","year":2024,"number":11,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true}},{"id":"L334","title":"Rastrear referentes e distinguir retomada de introdução","steps":["Separe os dois asteroides: o anunciado, que passou de raspão, e o da Sibéria, que não foi detectado. Atribuir uma oração ao objeto errado altera o sentido.","Na sequência hipotética, “qualquer detrito espacial” seria identificado e teria “sua trajetória” calculada. O possessivo retoma esse detrito.","Confira as demais retomadas no encadeamento: “isso” volta à pequena dimensão como explicação; “o que” resume a identificação e o cálculo prévios; a expressão asteroide da Sibéria recategoriza o objeto já mencionado."],"alternatives":{"A":"A oração caracteriza o OUTRO asteroide anunciado, não o meteoro da Sibéria.","B":"O possessivo sua liga a trajetória a qualquer detrito espacial, antecedente expresso na mesma construção.","C":"Isso é retrospectivo: retoma a explicação de que o corpo era pequeno demais, não a consequência posterior dos alarmes.","D":"O que retoma a possibilidade de identificação e cálculo antecipados; gastar os cartões aparece depois como consequência humorística.","E":"Asteroide da Sibéria retoma o meteoro inicial com outra designação; não introduz um novo referente."},"takeaway":"Substitua o pronome por seu antecedente e releia. Uma palavra nova pode designar um referente que já estava no texto.","authored":true,"key":"linguagens:L334","answer":"B","year":2025,"number":38,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"N001","title":"Toxina adquirida pela alimentação","steps":["O enunciado informa a origem do veneno: os sapos consomem insetos que se alimentam de plantas contendo essas substâncias.","A criação em cativeiro interrompe esse caminho alimentar. Sem a dieta natural apropriada, não há aquisição das toxinas descritas.","Não é necessário supor mutação, mudança de umidade ou uma adaptação evolutiva ocorrida durante a vida do indivíduo. A causa está explicitada na cadeia alimentar."],"alternatives":{"A":"Não há dado que relacione umidade à obtenção das toxinas.","B":"A ausência da alimentação natural interrompe a via pela qual a toxina chega aos anfíbios.","C":"A palavra adaptação é genérica; não substitui o mecanismo alimentar fornecido, nem implica evolução de indivíduos.","D":"Uma mudança comportamental não é apontada como a origem específica da perda de toxicidade.","E":"Não se relatam alterações genéticas; a diferença ambiental de dieta já explica o fenômeno."},"takeaway":"Não transforme toda mudança em adaptação genética. A presença de uma substância na cadeia não prova, por si só, biomagnificação quantitativa.","authored":true,"key":"natureza:N001","answer":"B","year":2025,"number":96,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"N625","title":"Duas propriedades, verificadas separadamente","steps":["O conforto de tocar o copo com café quente indica dificuldade de transmissão de calor para o exterior: baixa condutividade térmica.","O texto informa que metade do material é plástico reciclado NÃO biodegradável. Por isso, não se pode chamar o copo de totalmente biodegradável.","A reutilização e o retorno evitam a substituição por um novo descartável a cada uso, reduzindo o descarte não biodegradável no contexto dado. A alternativa deve satisfazer as duas condições."],"alternatives":{"A":"A presença de 50% de plástico não biodegradável contradiz “totalmente biodegradável”.","B":"Alta condutividade favoreceria o aquecimento externo, oposto à propriedade destacada.","C":"A baixa condutividade está correta, mas a vantagem ambiental não é aumentar resíduo na natureza.","D":"Combina o isolamento térmico indicado e a redução de descarte pelo reuso/retorno.","E":"Erra a condutividade e ainda atribui ao material uma degradação que o texto não garante."},"takeaway":"Em alternativas com duas afirmações, confira ambas. O item não é uma análise completa de ciclo de vida: não conclua impacto ambiental zero.","authored":true,"key":"natureza:N625","answer":"D","year":2023,"number":130,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true}},{"id":"N101","title":"RT-PCR e evidência de expressão gênica","steps":["A transcriptase reversa usa RNA como molde para formar DNA complementar, o cDNA. Depois, esse DNA pode ser amplificado.","No contexto de produção de proteínas, a presença de um RNA correspondente revela que aquele gene foi transcrito: está expresso.","A técnica não seleciona genes pela localização num plasmídeo, pela condição dominante ou por estarem em autossomos. O critério é a existência do RNA usado como molde."],"alternatives":{"A":"São os genes expressos que fornecem os transcritos de RNA detectados nesse contexto.","B":"Um gene plasmidial pode ou não estar expresso; localização não é o critério descrito.","C":"Ser bacteriano não garante ter um transcrito detectável naquele momento; a alternativa é ampla demais.","D":"Dominância descreve uma relação entre alelos/fenótipos, não o mecanismo de detecção de RNA.","E":"A distinção autossômico não explica a síntese de cDNA e não é o recorte desse sistema em procariotos."},"takeaway":"RT significa transcrição reversa neste contexto. Não confunda automaticamente RT-PCR com PCR quantitativa em tempo real; existem técnicas combinadas.","authored":true,"key":"natureza:N101","answer":"A","year":2024,"number":95,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true}},{"id":"N332","title":"Forças eletromotrizes e resistências internas","steps":["No modelo resistivo adotado pela questão, a lâmpada tem R = U²/P = 4,5²/4,5 = 4,5 Ω, calculado com as especificações nominais.","As três resistências internas somam 3 × 0,5 = 1,5 Ω, mesmo com uma pilha invertida. A resistência total é 6 Ω.","A pilha invertida se opõe às outras: a f.e.m. resultante é 1,5 + 1,5 − 1,5 = 1,5 V. Portanto, I = 1,5/6 = 0,25 A."],"alternatives":{"A":"0,25 A resulta da f.e.m. algébrica de 1,5 V dividida pela resistência total de 6 Ω.","B":"0,33 A é aproximadamente 1,5/4,5; deixa de incluir as resistências internas.","C":"0,75 A seria 4,5/6, isto é, o resultado sem inverter a f.e.m. de uma pilha.","D":"1,00 A é a corrente nominal P/U da lâmpada, não a corrente nas condições alteradas.","E":"1,33 A não satisfaz a lei da malha com f.e.m. de 1,5 V e resistência total de 6 Ω."},"takeaway":"Inverter uma pilha muda o sinal de sua f.e.m., não torna negativa sua resistência interna. As especificações não são a tensão real garantida nessa montagem.","authored":true,"key":"natureza:N332","answer":"A","year":2022,"number":119,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true}},{"id":"N494","title":"Calor sem necessidade de fluido","steps":["O comando pede o mecanismo de transferência de calor que independe de fluidos. Não pergunta o que inicialmente atrai a mariposa.","Na irradiação, energia é transportada por ondas eletromagnéticas, podendo atravessar inclusive o vácuo. Uma lâmpada aquecida pode transferir energia dessa forma.","Convecção envolve movimento de matéria num fluido. Reflexão, refração e dispersão são fenômenos ondulatórios, mas não são o nome do mecanismo térmico solicitado."],"alternatives":{"A":"Reflexão é mudança de direção no retorno de uma onda; não nomeia a transferência térmica pedida.","B":"Refração envolve mudança de propagação entre meios, não o mecanismo de aquecimento destacado.","C":"Irradiação transfere energia por ondas eletromagnéticas sem exigir fluido ou contato material.","D":"Dispersão relaciona-se à dependência da propagação com a frequência; não responde ao processo térmico.","E":"Convecção requer um fluido em movimento, contrariando a condição do enunciado."},"takeaway":"Diferencie causa da aproximação e consequência térmica. Presença de luz no texto não transforma toda alternativa de óptica em resposta.","authored":true,"key":"natureza:N494","answer":"C","year":2025,"number":95,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"N457","title":"Difração e capacidade de armazenamento","steps":["O texto relaciona a leitura de pequenas cavidades ao comprimento de onda: detalhes menores exigem comprimento de onda menor para reduzir a limitação por difração.","Entre as opções dadas, a ordem de comprimentos de onda crescentes é violeta, azul, verde, vermelho e infravermelho.","Logo, escolhe-se violeta. Em um mesmo meio, menor λ também corresponde a maior frequência pela relação v = λf. O recorte é entre as regiões listadas, não entre todas as tecnologias possíveis."],"alternatives":{"A":"Violeta tem o menor comprimento de onda entre as alternativas, favorecendo a leitura de detalhes menores.","B":"Azul é adequado a detalhes menores que vermelho, mas seu comprimento de onda é maior que o do violeta.","C":"Verde apresenta comprimento de onda maior que azul/violeta; não otimiza entre as opções.","D":"Vermelho tem comprimento de onda ainda maior e menor capacidade de distinguir as pequenas cavidades propostas.","E":"Infravermelho está além do vermelho em comprimento de onda; é a direção oposta à exigida."},"takeaway":"Observe se o objetivo exige aumentar ou diminuir a grandeza. Mais energia/frequência não significa maior comprimento de onda.","authored":true,"key":"natureza:N457","answer":"A","year":2023,"number":112,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true}},{"id":"N150","title":"Digestão intracelular e lisossomos","steps":["A descrição destaca falta de degradação de moléculas e acúmulo intracelular. A pergunta é sobre a estrutura que executa esse tipo de digestão.","Lisossomos contêm enzimas hidrolíticas atuantes em meio ácido. A deficiência da lipase ácida compromete a degradação lisossômica dos lipídios descritos.","Outras organelas participam da síntese, da energia ou de oxidações, mas não correspondem ao compartimento de digestão ácida indicado."],"alternatives":{"A":"Lisossomos são o compartimento digestivo cujas hidrolases incluem a atividade enzimática descrita.","B":"Ribossomos sintetizam proteínas; o texto não informa uma falha global de tradução, mas uma deficiência de degradação.","C":"Mitocôndrias realizam importantes etapas energéticas, não a digestão lisossômica ácida citada.","D":"Peroxissomos participam de reações oxidativas, mas não são o compartimento de ação dessa lipase ácida.","E":"O retículo liso atua, entre outras funções, na síntese de lipídios; não é a estrutura digestiva solicitada."},"takeaway":"Associe organela a PROCESSO, não apenas ao nome da molécula. “Lipídio” não implica automaticamente retículo liso.","authored":true,"key":"natureza:N150","answer":"A","year":2025,"number":103,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"N294","title":"Antígeno vacinal e imunidade ativa","steps":["A proteína spike funciona como antígeno: uma estrutura reconhecida pelo sistema imune. Não é um anticorpo pronto.","O contato com o antígeno pode induzir resposta adaptativa, incluindo anticorpos específicos e memória imunológica.","Como a resposta é produzida pelo próprio organismo, trata-se de imunização ativa. A questão não descreve edição do genoma humano nem substituição de receptores celulares."],"alternatives":{"A":"A produção de anticorpos específicos corresponde ao efeito imunológico esperado da apresentação desse antígeno.","B":"Imunidade passiva envolveria transferência de anticorpos prontos, como em certos soros; não é o mecanismo descrito.","C":"Memória imunológica não exige alterar o genoma humano por uma intervenção de edição gênica.","D":"A proteína antigênica não neutraliza diretamente os vírus; ela estimula uma resposta que pode realizar essa proteção.","E":"Não se propõe modificar os receptores das células humanas, mas reconhecer estruturas do vírus."},"takeaway":"Antígeno é reconhecido; anticorpo é um produto da resposta. A explicação do mecanismo não significa proteção absoluta contra toda infecção.","authored":true,"key":"natureza:N294","answer":"A","year":2024,"number":126,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true}},{"id":"N795","title":"Protonar uma amina para reduzir sua volatilidade","steps":["A dimetilamina é uma base orgânica volátil. No modelo da questão, uma opção ácida pode protonar a amina e favorecer uma forma iônica menos volátil.","O vinagre contém ácido acético. A reação pode ser representada por (CH₃)₂NH + CH₃COOH ⇌ (CH₃)₂NH₂⁺ + CH₃COO⁻.","Entre as opções, essa conversão ácido-base atende ao objetivo melhor que apenas diluir ou misturar com um material não ácido. É uma situação teórica de prova, não instrução de resposta a acidente."],"alternatives":{"A":"Água pode dissolver a substância, mas não é a opção ácida que promove de modo adequado a formação do sal pretendido.","B":"O ácido acético do vinagre protona a amina, favorecendo a forma iônica de menor volatilidade.","C":"Óleo de soja não oferece o tratamento ácido-base pedido; simples mistura não garante imobilização da amina.","D":"Sal de cozinha não fornece o ácido necessário para essa conversão.","E":"Bicarbonato tem comportamento básico usual e não é a opção ácida apropriada para protonar eficientemente a amina."},"takeaway":"Em acidente químico real, não manipule nem misture produtos: afaste-se e acione equipes especializadas. Aqui, avalia-se apenas o modelo ácido-base.","authored":true,"key":"natureza:N795","answer":"B","year":2025,"number":121,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true}},{"id":"N799","title":"Complexação pode puxar a dissolução do metal","steps":["O texto estabelece um equilíbrio entre alumínio imobilizado no vidro e alumínio em solução.","O gluconato pode ligar-se fortemente ao íon metálico. Ao diminuir a disponibilidade da forma livre em solução, favorece a passagem de mais alumínio do vidro para a fase líquida.","Maior concentração do complexante intensifica essa possibilidade: o alumínio total dissolvido pode aumentar, mesmo que sua fração livre seja consumida pela complexação."],"alternatives":{"A":"Translucidez não é a variável química apresentada como responsável pelo deslocamento do equilíbrio.","B":"Uma concentração alta de gluconato favorece a ligação ao alumínio e, pelo mecanismo descrito, sua dissolução.","C":"Espessura do vidro não determina, por si só, o deslocamento causado pelo complexante.","D":"Esterilização prévia não equivale à presença de maior concentração do reagente que complexa o metal durante o armazenamento.","E":"Saber apenas que uma reação seria endotérmica não estabelece a condição comparativa de maior contaminação pedida."},"takeaway":"Diferencie concentração livre e concentração total de uma espécie. Remover a forma livre por uma reação pode aumentar a dissolução do material de origem.","authored":true,"key":"natureza:N799","answer":"B","year":2023,"number":104,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true}},{"id":"H301","title":"Modernização agrícola e organismos não alvo","steps":["A mudança técnica descrita é a ampliação de inseticidas sintéticos na agricultura, sobretudo a partir dos anos 1960.","Além dos insetos considerados pragas, esses produtos podem afetar organismos não alvo, entre eles polinizadores. A perda de diversidade é um possível efeito ambiental.","O comando pede o que DIMINUI. Não se deve trocar o efeito sobre a biodiversidade por uma redução da contaminação ou por melhorias automáticas do solo."],"alternatives":{"A":"Desagregação das camadas do solo está ligada a processos de manejo/intemperismo; não é a redução indicada pelo uso de inseticidas.","B":"O efeito sobre insetos não alvo pode reduzir a diversidade de polinizadores naturais.","C":"O uso inadequado pode elevar riscos de contaminação; não justifica afirmar sua diminuição.","D":"A técnica foi difundida buscando produtividade; o efeito ambiental solicitado não é necessariamente queda da produção.","E":"Erosão laminar depende do escoamento superficial e da proteção/manejo do solo, não dessa diminuição específica."},"takeaway":"Leia o verbo do comando. Modernização pode aumentar produção e simultaneamente gerar impactos ambientais; não confunda objetivos e consequências.","authored":true,"key":"humanas:H301","answer":"B","year":2025,"number":75,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H778","title":"Representação coletiva e reconhecimento do outro","steps":["O fragmento aponta dois obstáculos: grupos fragmentados sem uma organização ampla e preconceito racial dirigido também à cultura negra.","O primeiro corresponde à precariedade de coesão representativa; o segundo, à recusa da alteridade, isto é, do reconhecimento do outro em sua diferença.","A resposta correta precisa preservar os dois eixos. O texto não diz que inexiste proteção constitucional nem que todas as religiões devam se fundir."],"alternatives":{"A":"Soluções partidárias e rejeição da laicidade não são os dois fatores descritos.","B":"Relaciona corretamente fragilidade organizativa e discriminação/recusa da diferença.","C":"Estruturas decisórias e dialogicidade não traduzem com a mesma precisão a organização ampla e o preconceito racial explicitados.","D":"Direitos constitucionais existem formalmente; sua falta de efetividade não equivale à inexistência. Ecumenismo não é o eixo do trecho.","E":"O texto não atribui a invisibilização à ausência de pertencimento étnico nem à brevidade de alianças políticas."},"takeaway":"Em alternativas com dois conceitos abstratos, faça duas correspondências com o texto, uma para cada termo.","authored":true,"key":"humanas:H778","answer":"B","year":2025,"number":74,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H574","title":"Nível do rio e custo da circulação de mercadorias","steps":["O rio é descrito como rota confiável de navegação, associada à implantação industrial em suas margens.","A redução do nível impede ou restringe a navegação. Cargas podem exigir viagens menores/mais numerosas ou substituição por outros modais.","Esse encadeamento eleva custos logísticos. O texto não demonstra fim da mineração, colapso da agricultura nem envelhecimento físico das fábricas."],"alternatives":{"A":"A interrupção da extração mineral não é informada; o problema apresentado está no transporte.","B":"Não há indicação de aumento da pesca como consequência econômica central.","C":"Restrições à navegação dificultam a circulação de cargas e encarecem a logística.","D":"Agricultura de subsistência não é a atividade focalizada no trecho sobre navegação e indústrias.","E":"Sucateamento significa perda/obsolescência do parque industrial, algo não demonstrado pelo aumento da dificuldade logística."},"takeaway":"Construa uma cadeia causal curta: ambiente → circulação → custo. Evite ampliar uma consequência além da evidência fornecida.","authored":true,"key":"humanas:H574","answer":"C","year":2025,"number":56,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H447","title":"Soluções baseadas na natureza na cidade","steps":["O texto relaciona ondas de calor, alagamentos e vulnerabilidade social, pedindo uma medida que atenue esses problemas com apoio na natureza.","Parques bem planejados podem oferecer vegetação, sombra e superfícies permeáveis, contribuindo para resfriamento e manejo da água da chuva.","Entre as alternativas, é a intervenção compatível com essa abordagem. Isso não significa que qualquer parque resolva sozinho a desigualdade ou dispense drenagem e outras políticas."],"alternatives":{"A":"Faixas sinalizadoras podem comunicar riscos, mas não são a solução baseada na natureza destacada.","B":"Incineração não cria a infraestrutura verde/permeável indicada para calor e alagamentos.","C":"Parques podem combinar vegetação, infiltração e amenização térmica, atendendo ao recorte da questão.","D":"Verticalização pode integrar outros debates urbanos, mas não é por si a medida natural de adaptação pedida.","E":"Estacionamentos convencionais ampliam superfícies impermeáveis; não correspondem à estratégia proposta."},"takeaway":"Conecte a medida ao mecanismo: menos impermeabilização, mais retenção/infiltração e resfriamento. Considere acesso e justiça socioambiental.","authored":true,"key":"humanas:H447","answer":"C","year":2024,"number":88,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true}},{"id":"H484","title":"Uma mobilidade acessível a grupos específicos","steps":["O autor critica a generalização da expressão êxodo urbano. Seu argumento observa quem pode comprar segunda residência ou mudar mantendo renda e emprego.","Essas possibilidades concentram-se numa pequena fração de alta renda, e não em toda a população urbana.","Portanto, os deslocamentos são seletivos socialmente. A aparente ida ao interior pode preservar padrões de vida urbanos e não indicar retorno generalizado às tradições rurais."],"alternatives":{"A":"O texto afirma que parte dos migrantes conserva uma vida urbana, não que adota necessariamente tradições rurais.","B":"Redução de plantações não é apresentada como explicação da crítica.","C":"Não se demonstra estagnação do comércio; a análise se concentra no perfil de quem se desloca.","D":"Infraestrutura rodoviária não é o fator central apontado para a seletividade.","E":"A renda e a estabilidade no trabalho delimitam quem pode realizar os deslocamentos descritos."},"takeaway":"Para analisar migrações, pergunte quem se move, com quais recursos e em que condições. Não generalize a experiência de uma elite.","authored":true,"key":"humanas:H484","answer":"E","year":2025,"number":54,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H002","title":"Caridade colonial e salvação religiosa","steps":["Situe a fonte: a instituição de Salvador é de 1726, no período colonial. O acolhimento de recém-nascidos é apresentado junto de caridade, paternalismo e batismo.","A justificativa associa uma necessidade social à salvação da alma, especialmente diante da mortalidade elevada.","A expressão que reúne essas dimensões é preceito sociorreligioso. Não se deve projetar automaticamente a linguagem contemporânea dos direitos humanos sobre a motivação indicada no texto."],"alternatives":{"A":"A defesa moderna de direitos humanos não é a justificativa explicitada para essa instituição colonial.","B":"Caridade e cuidado social articulados ao batismo e à salvação configuram a natureza sociorreligiosa.","C":"O acolhimento de abandonados não tem como motivação apresentada reconhecer vínculos familiares.","D":"O eixo justificativo não é técnico-científico; é sobretudo caritativo e religioso.","E":"Abolicionismo não é a finalidade atribuída à Roda dos Expostos no fragmento."},"takeaway":"Diferencie uma prática de assistência e a justificativa histórica que a sustenta. Evite anacronismos sem ignorar o cuidado material existente.","authored":true,"key":"humanas:H002","answer":"B","year":2025,"number":78,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H356","title":"Nome do país e integração regional","steps":["A fonte explica o impasse: a Grécia se opunha ao nome Macedônia e bloqueava negociações de adesão do país vizinho à União Europeia.","A mudança para Macedônia do Norte atende ao acordo e remove esse obstáculo diplomático.","Para o Estado que muda o nome, a estratégia é aprofundar a integração regional. O texto não trata de anexação territorial, imposição sobre minorias nem criação de moeda."],"alternatives":{"A":"Não há relação apresentada entre o acordo e a criação de moeda própria.","B":"A motivação descrita é desbloquear negociações regionais, não proteger uma cultura de influência externa.","C":"Subjugar minorias não é medida mencionada ou consequência defendida no trecho.","D":"A mudança do nome não altera, por si, as fronteiras do país.","E":"Responde diretamente ao desbloqueio das negociações de adesão e à aproximação regional."},"takeaway":"Leia os fatos no tempo da fonte. Liberar negociações de adesão não significa afirmar que o país já se tornou membro da União Europeia.","authored":true,"key":"humanas:H356","answer":"E","year":2025,"number":46,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H690","title":"Disciplina como controle distribuído no cotidiano","steps":["O texto descreve processos mínimos, dispersos e progressivos, e cita colégios, escolas, hospitais e organização militar.","A repetição de práticas em instituições diversas revela difusão do controle sobre corpos, condutas, espaços e tempos.","“Capilarização” nomeia esse alcance nas relações cotidianas. Não se trata apenas de uma lei central ou de uma punição pública espetacular."],"alternatives":{"A":"Suplício remete à punição corporal exemplar; não resume a disciplina cotidiana e disseminada apresentada.","B":"A disciplina não se reduz à judicialização: opera também em rotinas de instituições não judiciais.","C":"O texto não explica a dissolução da nobreza; descreve técnicas e espaços de controle.","D":"Expressa a disseminação das práticas de controle em múltiplos pontos da vida social.","E":"Espetáculo de penitência não corresponde ao funcionamento difuso, repetido e cotidiano enfatizado."},"takeaway":"Em Foucault, observe o funcionamento concreto das relações de poder, não apenas a existência de Estado, tribunais ou violência visível.","authored":true,"key":"humanas:H690","answer":"D","year":2025,"number":55,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H729","title":"Igualdade formal e proteção direcionada","steps":["A autora mostra que igualdade abstrata pode coexistir com inferiorização social de mulheres. Uma política direcionada busca enfrentar uma desigualdade concreta.","A chamada discriminação positiva não significa inferioridade natural: refere-se a uma ação específica de proteção/equidade diante de barreiras sociais.","Entre as opções, delegacias especializadas constituem atendimento institucional direcionado à violência enfrentada por mulheres."],"alternatives":{"A":"Sufrágio universal é um direito geral importante, mas não é a medida direcionada de proteção apresentada nas opções.","B":"Redução genérica da jornada não identifica, por si, a política específica solicitada.","C":"Extinguir o crime de feminicídio retiraria proteção, em sentido contrário ao enfrentamento da violência.","D":"Reduzir licença-maternidade restringiria um direito, não exemplificaria a proteção proposta.","E":"A delegacia especializada oferece uma resposta institucional direcionada a uma desigualdade e violência específicas."},"takeaway":"Igualdade de direitos e equidade não são opostos. Uma medida pode ser diferenciada para enfrentar obstáculos desigualmente distribuídos.","authored":true,"key":"humanas:H729","answer":"E","year":2025,"number":81,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}},{"id":"H151","title":"Escrita das leis e conflito entre patrícios e plebeus","steps":["O texto associa a transmissão oral das leis à possibilidade de os patrícios manipularem a justiça. O problema é o controle desigual das regras.","Na Roma republicana, as lutas plebeias buscaram reconhecimento político e garantias jurídicas, incluindo publicidade/escrita das leis.","Portanto, o grupo que contesta essa conjuntura é a plebe. Não se trata de uma reivindicação sobre jornada de trabalho, nem de um movimento de estrangeiros no fragmento."],"alternatives":{"A":"Monarcas não são o grupo apontado pelas disputas republicanas contra o monopólio patrício.","B":"Os plebeus buscavam participação e proteção frente ao controle patrício sobre normas e instituições.","C":"Os nobres/patrícios eram os beneficiários do quadro descrito; a alternativa não identifica o grupo contestador.","D":"Camponeses é uma categoria ocupacional; a demanda de reduzir jornada não aparece no texto e não explica o conflito jurídico.","E":"O recorte é o conflito entre patrícios e plebeus, não a abertura de espaços públicos a estrangeiros."},"takeaway":"Plebeu não é sinônimo de escravizado nem necessariamente de pobre. Compare posição política, condição jurídica e ocupação sem misturá-las.","authored":true,"key":"humanas:H151","answer":"B","year":2025,"number":87,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true}}];
